import java.util.Arrays;

public class EqualRunSegmenterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("segments({4,4,7,7,7,1})", "[[4, 2], [7, 3], [1, 1]]",
                    Arrays.deepToString(EqualRunSegmenter.segments(new int[] {4, 4, 7, 7, 7, 1})));
            check("segments({}) has no runs", "[]",
                    Arrays.deepToString(EqualRunSegmenter.segments(new int[] {})));
            check("segments({5})", "[[5, 1]]",
                    Arrays.deepToString(EqualRunSegmenter.segments(new int[] {5})));
            check("segments({2,2,2,2})", "[[2, 4]]",
                    Arrays.deepToString(EqualRunSegmenter.segments(new int[] {2, 2, 2, 2})));
            check("segments({1,2,3})", "[[1, 1], [2, 1], [3, 1]]",
                    Arrays.deepToString(EqualRunSegmenter.segments(new int[] {1, 2, 3})));
            check("segments({0,0,-3,-3,0})", "[[0, 2], [-3, 2], [0, 1]]",
                    Arrays.deepToString(EqualRunSegmenter.segments(new int[] {0, 0, -3, -3, 0})));
            int[] source = {8, 8, 1};
            EqualRunSegmenter.segments(source);
            check("input array untouched", "[8, 8, 1]", Arrays.toString(source));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

