public class EqualRunSegmenter {

    public static int[][] segments(int[] values) {
        if (values.length == 0) {
            return new int[0][];
        }
        int runs = 1;
        for (int i = 1; i < values.length; i++) {
            if (values[i] != values[i - 1]) {
                runs++;
            }
        }
        int[][] result = new int[runs][2];
        int row = 0;
        result[0][0] = values[0];
        result[0][1] = 1;
        for (int i = 1; i < values.length; i++) {
            if (values[i] == values[i - 1]) {
                result[row][1]++;
            } else {
                row++;
                result[row][0] = values[i];
                result[row][1] = 1;
            }
        }
        return result;
    }
}
